                states: ("idle" | "sleeping" | "low_energy" | "hungry" | "sick" | "playing" | "accident" | "chewing" | "scratching")[];
                /** @description When the URLs above stop working (ISO 8601); fetch the state again before. */
                expires_at: string | null;
